  async migrationsReady(){const relations=await this.pool.query("SELECT to_regclass('public.schema_migrations') ledger,to_regclass('public.endpoints') endpoints");if(!relations.rows[0]?.ledger||!relations.rows[0]?.endpoints)return false;const names=(await readdir(migrationDirectory)).filter(x=>/^\d{4}_.+\.sql$/.test(x));const required=new Map(await Promise.all(names.map(async name=>[name,digest(await readFile(`${migrationDirectory}/${name}`,"utf8"))] as const)));const applied=new Map((await this.pool.query("SELECT name,checksum FROM schema_migrations WHERE name=ANY($1::text[])",[names])).rows.map(row=>[String(row.name),String(row.checksum)]));return [...required].every(([name,checksum])=>applied.get(name)===checksum)}
  private async tx<T>(fn:(c:PoolClient)=>Promise<T>){const c=await this.pool.connect();try{await c.query("BEGIN");const result=await fn(c);await c.query("COMMIT");return result}catch(e){await c.query("ROLLBACK");throw e}finally{c.release()}}
  private async lockUsers(c:PoolClient,ids:string[]){const unique=[...new Set(ids)].sort();if(unique.length)await c.query("SELECT id FROM users WHERE id=ANY($1::uuid[]) ORDER BY id FOR UPDATE",[unique])}
  async isPlatformOwner(userId:string){return Boolean((await this.pool.query("SELECT is_platform_owner FROM users WHERE id=$1",[userId])).rows[0]?.is_platform_owner)}
  async platformSettings(){const r=await this.pool.query("SELECT registration_open \"registrationOpen\",max_workspaces_per_user \"maxWorkspacesPerUser\",max_endpoints_per_workspace \"maxEndpointsPerWorkspace\",endpoint_expiry_grace_hours \"endpointExpiryGraceHours\" FROM platform_settings WHERE id=true");return r.rows[0]??{registrationOpen:false,maxWorkspacesPerUser:5,maxEndpointsPerWorkspace:10,endpointExpiryGraceHours:24}}

