  async setSharedNodePoolAccess(nodeId:string,enabled:boolean,labels:Record<string,string>,actorUserId:string){return this.tx(async c=>{const node=(await c.query("SELECT id,workspace_id FROM nodes WHERE id=$1 AND revoked_at IS NULL FOR UPDATE",[nodeId])).rows[0];if(!node)throw new DatabaseError("not_found","node not found");if(enabled)await c.query("UPDATE nodes SET workspace_id=NULL,updated_at=now() WHERE id=$1",[nodeId]);await c.query("INSERT INTO platform_node_pool(node_id,enabled,labels,updated_by) VALUES($1,$2,$3,$4) ON CONFLICT(node_id) DO UPDATE SET enabled=EXCLUDED.enabled,labels=EXCLUDED.labels,updated_by=EXCLUDED.updated_by,updated_at=now()",[nodeId,enabled,labels,actorUserId]);if(!enabled){const grants=(await c.query("SELECT workspace_id FROM workspace_node_pool_grants WHERE node_id=$1",[nodeId])).rows;for(const grant of grants)await c.query("UPDATE endpoints SET node_id=NULL,updated_at=now() WHERE workspace_id=$1 AND node_id=$2",[grant.workspace_id,nodeId]);await c.query("DELETE FROM workspace_node_pool_grants WHERE node_id=$1",[nodeId])}return(await c.query("SELECT node_id \"nodeId\",enabled,labels,updated_at \"updatedAt\" FROM platform_node_pool WHERE node_id=$1",[nodeId])).rows[0]})}
  async grantSharedNode(workspaceId:string,nodeId:string,actorUserId:string){return this.tx(async c=>{const workspace=await c.query("SELECT 1 FROM workspaces WHERE id=$1",[workspaceId]);if(!workspace.rowCount)throw new DatabaseError("not_found","workspace not found");const pool=await c.query("SELECT 1 FROM platform_node_pool p JOIN nodes n ON n.id=p.node_id WHERE p.node_id=$1 AND p.enabled AND n.revoked_at IS NULL FOR UPDATE OF p",[nodeId]);if(!pool.rowCount)throw new DatabaseError("conflict","node is not enabled in shared pool");await c.query("INSERT INTO workspace_node_pool_grants(workspace_id,node_id,created_by) VALUES($1,$2,$3) ON CONFLICT DO NOTHING",[workspaceId,nodeId,actorUserId])})}
