  async platformNodes(){return(await this.pool.query("SELECT n.id,n.workspace_id \"workspaceId\",n.name,n.remark,n.provider,n.labels,n.last_heartbeat_at \"lastHeartbeatAt\",p.enabled,p.updated_at \"updatedAt\",COALESCE((SELECT array_agg(g.workspace_id) FROM workspace_node_pool_grants g WHERE g.node_id=n.id),'{}') \"grantedWorkspaceIds\" FROM nodes n LEFT JOIN platform_node_pool p ON p.node_id=n.id WHERE n.revoked_at IS NULL ORDER BY n.created_at")).rows}

