  async endpointNapcatSnapshot(workspaceId:string,id:string){const r=await this.pool.query(`SELECT e.provider_id,o.state,o.created_at observation_created_at,n.last_heartbeat_at node_last_heartbeat_at,now() checked_at,(o.created_at BETWEEN now()-interval '15 seconds' AND now()) observation_fresh,(n.last_heartbeat_at BETWEEN now()-make_interval(secs => $3) AND now()) node_online FROM endpoints e LEFT JOIN nodes n ON n.id=e.node_id LEFT JOIN LATERAL (SELECT state,created_at FROM observations WHERE endpoint_id=e.id ORDER BY created_at DESC LIMIT 1) o ON true WHERE e.workspace_id=$1 AND e.id=$2 AND e.deleted_at IS NULL`,[workspaceId,id,nodeFreshMs/1000]);const row=r.rows[0];if(!row)throw new DatabaseError("not_found");if(row.provider_id!=="napcat")throw new DatabaseError("conflict","provider is not NapCat");return{metadata:((row.state as Record<string,unknown>|null)?.metadata as Record<string,unknown>|undefined)??{},observationAt:row.observation_created_at?new Date(row.observation_created_at).toISOString():null,nodeHeartbeatAt:row.node_last_heartbeat_at?new Date(row.node_last_heartbeat_at).toISOString():null,checkedAt:new Date(row.checked_at).toISOString(),observationFresh:Boolean(row.observation_fresh),nodeOnline:Boolean(row.node_online)}}
