  async claimAgentCommand(nodeId:string,sessionId:string){return this.tx(async c=>{const node=(await c.query("SELECT connection_epoch,connection_session_id FROM nodes WHERE id=$1 AND revoked_at IS NULL FOR UPDATE",[nodeId])).rows[0];if(!node)throw new DatabaseError("unauthorized");if(node.connection_session_id!==sessionId)throw new DatabaseError("conflict","claim session fence rejected");const r=await c.query(`SELECT * FROM agent_commands WHERE node_id=$1 AND connection_epoch=$2 AND status IN ('queued','leased') AND (status='queued' OR lease_deadline<now()) ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1`,[nodeId,node.connection_epoch]);const command=r.rows[0];if(!command)return null;if(Number(command.attempts)>=maxCommandAttempts){const result={reason:"attempt_budget_exhausted",attempts:Number(command.attempts)};await c.query("UPDATE agent_commands SET status='failed',result_at=now(),result=$2,updated_at=now() WHERE id=$1",[command.id,result]);await c.query("UPDATE operations SET status='failed',result=$2,updated_at=now() WHERE id=$1 AND status='running'",[command.operation_id,result]);return null}const leased=(await c.query("UPDATE agent_commands SET status='leased',attempts=attempts+1,lease_deadline=now()+interval '30 seconds',updated_at=now() WHERE id=$1 RETURNING *",[command.id])).rows[0];await c.query("UPDATE operations SET command_attempt=command_attempt+1,lease_deadline=now()+interval '30 seconds',updated_at=now() WHERE id=$1",[leased.operation_id]);return mapCommand(leased)})}
